namespace Tsumo.Cli
{
    public class LanguageConfig
    {
        public string lang;
        public string languageName;
        public string languageDirection;
        public string contentDir;
        public int weight;
        public LanguageConfig(string lang, string languageName, string languageDirection, string contentDir, int weight)
        {
            this.lang = lang;
            this.languageName = languageName;
            this.languageDirection = languageDirection;
            this.contentDir = contentDir;
            this.weight = weight;
        }
    }
    public class LanguageContext
    {
        public string Lang;
        public string LanguageName;
        public string LanguageDirection;
        public LanguageContext(string lang, string languageName, string languageDirection)
        {
            this.Lang = lang;
            this.LanguageName = languageName;
            this.LanguageDirection = languageDirection;
        }
    }
}
